update  dbo.gbqWatermark
set     LoadedDateUtc = '@{formatDateTime(utcNow(), 'yyyy-MM-dd HH:mm:ss.fff')}',
        DestinationUri = '@{activity('Get Pipeline Parameters').output.firstRow.SinkdsDirectory}/@{item().FilePath}/@{item().FilePath}/@{item().FileName}',
        RowCountDest = @{activity('BatchToParquet').output.rowsCopied} 
where   TableCatalog = '@{item().TableCatalog}'
    and TableSchema = '@{item().TableSchema}'
    and TableName = '@{item().TableName}'
    and BatchId = @{item().BatchId}
    @{if(equals(item().SubBatchId, null), '', concat(' and SubBatchId = ', item().SubBatchId))}
    @{if(equals(item().PartitionId, null), '', concat(' and PartitionId = ', item().PartitionId))}
